import { WheelPicker } from '@larose-ui/react';
import { useState } from 'react';

const columns = [
  {
    id: 'hour',
    label: 'Hour',
    options: [
      { value: '09', label: '09' },
      { value: '10', label: '10' },
      { value: '11', label: '11' },
    ],
  },
  {
    id: 'minute',
    label: 'Minute',
    options: [
      { value: '00', label: '00' },
      { value: '15', label: '15' },
      { value: '30', label: '30' },
    ],
  },
];

export default function App() {
  const [value, setValue] = useState({ hour: '09', minute: '00' });
  return <WheelPicker columns={columns} value={value} onChange={setValue} aria-label="Time" />;
}
